// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DA SHOPIFY (TAGS, LINE ITEMS, FULFILLMENT)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

// 1. Extração e sanitização do cliente
const customer = body.customer || {};
let rawPhone = (customer.phone || customer.default_address?.phone || body.billing_address?.phone || body.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const firstName = customer.first_name || body.billing_address?.first_name || 'Cliente';
const lastName = customer.last_name || body.billing_address?.last_name || '';
const clienteNome = `${firstName} ${lastName}`.trim();
const clienteEmail = (customer.email || body.email || body.contact_email || '').trim().toLowerCase();
const customerTags = (customer.tags || '').split(',').map(t => t.trim()).filter(Boolean);

// 2. Valores e pedidos
const numeroPedido = parseInt(body.order_number || body.number || body.id || Date.now(), 10);
const valorTotal = parseFloat(body.total_price || body.current_total_price || 0);
const valorFrete = parseFloat(body.total_shipping_price_set?.shop_money?.amount || body.shipping_lines?.[0]?.price || 0);
const financialStatus = (body.financial_status || 'pending').toLowerCase();
const fulfillmentStatus = (body.fulfillment_status || 'unfulfilled').toLowerCase();

let statusOperacional = 'Pendente';
if (['paid', 'authorized'].includes(financialStatus)) {
  statusOperacional = 'Pago';
} else if (['refunded', 'voided'].includes(financialStatus)) {
  statusOperacional = 'Cancelado';
}

if (fulfillmentStatus === 'fulfilled') {
  statusOperacional = 'Enviado';
}

// 3. Parsing dos Itens
const lineItems = (body.line_items || []).map(li => ({
  produto_nome: li.title || li.name || 'Produto',
  sku: li.sku || 'SHOPIFY_SKU',
  quantidade: parseInt(li.quantity || 1, 10),
  preco_venda: parseFloat(li.price || 0)
}));

const dedupHash = crypto.createHash('sha256').update(`shopify_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_tags: customerTags,
    valor_total: valorTotal,
    valor_frete: valorFrete,
    status_operacional: statusOperacional,
    line_items: lineItems
  }
}];
